1	export const dynamic = "force-dynamic";
2	
3	import { requireUser } from "@/lib/auth";
4	import { db } from "@/lib/db";
5	import { categoryOf } from "@/lib/nx/activity";
6	import { ActivityView } from "@/components/nx/ActivityView";
7	
8	/* Activity, on the concept's structure.
9	 *
10	 * The category counts are computed over the SAME rows the table shows, in this
11	 * one place — not a separate aggregate query that could disagree with the list
12	 * beside it. Categorising happens on read (see lib/nx/activity.ts) so the
13	 * hundreds of rows written before `AuditLog.category` existed group exactly
14	 * like new ones, with no backfill and no history rewrite.
15	 */
16	export default async function ActivityPage({
17	  searchParams,
18	}: { searchParams: Promise<{ days?: string }> }) {
19	  const user = await requireUser();
20	  const sp = await searchParams;
21	
22	  /* A closed set — this becomes a date boundary in a query. */
23	  const days = [7, 30, 90].includes(Number(sp.days)) ? Number(sp.days) : 30;
24	  const since = new Date(Date.now() - days * 86_400_000);
25	  const prevSince = new Date(Date.now() - days * 2 * 86_400_000);
26	
27	  const [rows, prevCount, sessionCount] = await Promise.all([
28	    db.auditLog.findMany({
29	      where: { userId: user.id, createdAt: { gte: since } },
30	      select: {
31	        id: true, action: true, detail: true, target: true, ip: true,
32	        category: true, createdAt: true,
33	      },
34	      orderBy: { createdAt: "desc" },
35	      take: 400,
36	    }),
37	    /* The window immediately before this one, so "vs previous" compares like
38	       with like rather than against an arbitrary calendar month. */
39	    db.auditLog.count({
40	      where: { userId: user.id, createdAt: { gte: prevSince, lt: since } },
41	    }),
42	    db.userSession.count({ where: { userId: user.id, createdAt: { gte: since } } }),
43	  ]);
44	
45	  const events = rows.map((r) => ({
46	    id: r.id,
47	    action: r.action,
48	    /* Stored category wins where present; older rows fall through to the same
49	       mapping, so the two kinds are indistinguishable in the list. */
50	    category: r.category ?? categoryOf(r.action),
51	    detail: r.detail ?? "",
52	    target: r.target ?? "",
53	    ip: r.ip ?? "",
54	    at: r.createdAt.toISOString(),
55	  }));
56	
57	  const counts: Record<string, number> = {};
58	  for (const e of events) counts[e.category] = (counts[e.category] ?? 0) + 1;
59	
60	  return (
61	    <ActivityView
62	      who={user.name || user.email.split("@")[0]}
63	      days={days}
64	      events={events}
65	      counts={counts}
66	      total={events.length}
67	      prevTotal={prevCount}
68	      /* Login sessions come from UserSession, which is new and empty until
69	         sign-ins start being recorded — shown as such rather than as zero. */
70	      sessions={sessionCount}
71	      sessionsTracked={sessionCount > 0}
72	    />
73	  );
74	}
