32	  ...ALLOWED_IMAGE_MIME,
33	  "application/pdf",
34	  ".pdf",
35	  "text/plain",
36	  ".txt",
37	  ".log",
38	  "application/zip",
39	  ".zip",
40	].join(",");
41	
42	/**
43	 * Hard cap: 10 MB. A support attachment (log dump, screenshot, small PDF) runs
44	 * larger than a chat image; still well short of anything that would strain
45	 * storing bytes in Postgres. Enforced server-side regardless of any client check.
46	 */
47	export const MAX_TICKET_ATTACHMENT_BYTES = 10 * 1024 * 1024;
48	
49	export type TicketAttachmentValidation =
50	  | { ok: true; mime: string; bytes: Buffer }
51	  | { ok: false; error: string };
52	
53	function sniffPdf(buf: Buffer): boolean {
54	  // "%PDF"
55	  return buf.length >= 4 && buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46;
56	}
57	
58	function sniffZip(buf: Buffer): boolean {
59	  if (buf.length < 4) return false;
60	  // Local file header "PK\x03\x04", empty archive "PK\x05\x06", spanned "PK\x07\x08".
61	  if (buf[0] !== 0x50 || buf[1] !== 0x4b) return false;
62	  return (
63	    (buf[2] === 0x03 && buf[3] === 0x04) ||
64	    (buf[2] === 0x05 && buf[3] === 0x06) ||
65	    (buf[2] === 0x07 && buf[3] === 0x08)
66	  );
67	}
68	
69	/**
70	 * Plain text/log has no magic number. Instead of trusting the extension alone,
71	 * reject anything that looks binary — a NUL byte, or a high proportion of
72	 * non-printable bytes, in the first 8 KB — the same heuristic tools like git
73	 * use to tell text from binary. This does not "validate" the content, it just
74	 * keeps an executable or image mislabeled as .txt from being accepted as one.
75	 */
76	function looksLikeText(buf: Buffer): boolean {
77	  const sample = buf.subarray(0, 8192);
78	  if (sample.length === 0) return true;
79	  let suspicious = 0;
80	  for (let i = 0; i < sample.length; i++) {
81	    const b = sample[i];
82	    if (b === 0) return false; // NUL byte: never text
83	    // Allow common whitespace control chars; count everything else below 0x20 as suspicious.
84	    if (b < 0x09 || (b > 0x0d && b < 0x20)) suspicious++;
85	  }
86	  return suspicious / sample.length < 0.05;
87	}
88	
89	function extOf(filename: string | null | undefined): string {
90	  return (filename ?? "").toLowerCase().match(/\.[a-z0-9]{1,8}$/)?.[0] ?? "";
91	}
92	
93	/**
94	 * Full server-side validation of a ticket attachment (image OR document).
95	 * Enforces, in order: non-empty, size ≤ cap, then dispatches to the right
96	 * signature check based on what the bytes actually look like — the declared
97	 * MIME/filename are only ever used to pick which check to try first, never
98	 * trusted on their own.
99	 */
100	export function validateTicketAttachmentBytes(
101	  bytes: Buffer | Uint8Array,
102	  declaredMime?: string | null,
103	  filename?: string | null
104	): TicketAttachmentValidation {
105	  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
106	
107	  if (buf.length === 0) return { ok: false, error: "Empty file." };
108	  if (buf.length > MAX_TICKET_ATTACHMENT_BYTES) {
109	    return { ok: false, error: "File is larger than 10 MB." };
110	  }
111	
112	  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
113	  if (declared === "image/svg+xml") {
114	    return { ok: false, error: "SVG images are not allowed." };
115	  }
116	
117	  // 1. Image — delegate to the shared image sniffer/allow-list.
118	  const sniffedImage = sniffImageMime(buf);
119	  if (sniffedImage) {
120	    if (declared && isAllowedImageMime(declared) && declared !== sniffedImage) {
121	      return { ok: false, error: "Image contents do not match its declared type." };
122	    }
123	    return { ok: true, mime: sniffedImage, bytes: buf };
124	  }
125	  if (declared && isAllowedImageMime(declared)) {
126	    // Claimed to be an allow-listed image but failed the byte signature check.
127	    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
128	  }
129	
130	  // 2. PDF
131	  if (sniffPdf(buf)) return { ok: true, mime: "application/pdf", bytes: buf };
132	  if (declared === "application/pdf") {
133	    return { ok: false, error: "File is not a valid PDF." };
134	  }
135	
136	  // 3. ZIP
137	  if (sniffZip(buf)) return { ok: true, mime: "application/zip", bytes: buf };
138	  if (declared === "application/zip" || declared === "application/x-zip-compressed") {
139	    return { ok: false, error: "File is not a valid ZIP archive." };
140	  }
141	
142	  // 4. Plain text / log — no magic number, so lean on extension + a binary-content check.
143	  const ext = extOf(filename);
144	  const looksLikeTextFile = declared === "text/plain" || ext === ".txt" || ext === ".log";
145	  if (looksLikeTextFile) {
146	    if (!looksLikeText(buf)) {
147	      return { ok: false, error: "File does not look like a plain-text/log file." };
148	    }
149	    return { ok: true, mime: "text/plain", bytes: buf };
150	  }
151	
152	  return {
153	    ok: false,
154	    error: "Unsupported file type. Allowed: images, PDF, TXT, LOG, or ZIP.",
155	  };
156	}
157	
158	export function isImageMime(mime: string): mime is AllowedImageMime {
159	  return isAllowedImageMime(mime);
160	}
